from solution import median_numbers
import inspect


def test_issue_example_25_55_65():
    """Example assert median_numbers(25,55,65)==55.0."""
    assert median_numbers(25, 55, 65) == 55.0  # sorted [25,55,65] middle is 55 -> 55.0


def test_issue_median_as_first_arg():
    """Median of three numbers is middle value after sorting."""
    assert median_numbers(55, 25, 65) == 55.0  # sorted [25,55,65] middle is 55 -> 55.0


def test_issue_median_as_last_arg():
    """Median of three numbers is middle value after sorting."""
    assert median_numbers(25, 65, 55) == 55.0  # sorted [25,55,65] middle is 55 -> 55.0


def test_issue_descending_order():
    """Median of three numbers is middle value after sorting."""
    assert median_numbers(65, 55, 25) == 55.0  # sorted [25,55,65] middle is 55 -> 55.0


def test_issue_all_three_equal():
    """Median of three numbers is middle value after sorting."""
    assert median_numbers(7, 7, 7) == 7.0  # sorted [7,7,7] middle is 7 -> 7.0


def test_issue_two_equal_low_is_median():
    """Median of three numbers is middle value after sorting."""
    assert median_numbers(10, 10, 20) == 10.0  # sorted [10,10,20] middle is 10 -> 10.0


def test_issue_two_equal_high_is_median():
    """Median of three numbers is middle value after sorting."""
    assert median_numbers(10, 20, 20) == 20.0  # sorted [10,20,20] middle is 20 -> 20.0


def test_issue_negative_values():
    """Median of three numbers is middle value after sorting."""
    assert median_numbers(-10, -5, -1) == -5.0  # sorted [-10,-5,-1] middle is -5 -> -5.0


def test_issue_crosses_zero():
    """Median of three numbers is middle value after sorting."""
    assert median_numbers(-5, 0, 5) == 0.0  # sorted [-5,0,5] middle is 0 -> 0.0


def test_issue_float_values():
    """Median of three numbers is middle value after sorting."""
    assert median_numbers(1.5, 3.5, 2.5) == 2.5  # sorted [1.5,2.5,3.5] middle is 2.5 -> 2.5


def test_contract_is_callable():
    """Public interface median_numbers is a callable function."""
    assert callable(median_numbers) is True  # callable check passes -> True


def test_contract_takes_three_parameters():
    """Public interface def median_numbers(a, b, c) takes three parameters."""
    assert len(inspect.signature(median_numbers).parameters) == 3  # params a,b,c count = 3
